(ROOT/'probe-extract.mjs').write_text("\nimport {readFileSync,writeFileSync} from 'node:fs';import{execFileSync}from'node:child_process';import{gzipSync}from'node:zlib';\nimport{ASSETS}from'./src/data/market-history.js';import{qualifyHistoryWindow}from'./src/data/history-window-quality.js';import{getAnnualReturnStartYears}from'./src/pages/tweet-midi/data/performanceHistory.js';import{references}from'./src/pages/dca-profiles/engine.js';import{portfolioAnalytics}from'./src/pages/dca-profiles/analytics.js';import{SHEETS}from'./src/pages/factsheet-tweets/data.js';import{INDEX_FACTS,CURRENT_INDEX_KEYS,CURRENT_INDEX_SNAPSHOTS}from'./src/data/index-facts.js';import{getIndexConcentration}from'./src/data/index-company-compositions.js';\nconst out=process.env.RECIPE_OUTPUT,now=new Date(),monthly=JSON.parse(readFileSync('scripts/monthly-automation.json')),controls=JSON.parse(readFileSync('scripts/source-snapshots/monthly-collection-status.json')).series,config=new Map(monthly.series.map(r=>[r.id,r])),manifest=JSON.parse(readFileSync('src/pages/dca-profiles/holdings-manifest.json')),holdings=Object.assign({},...[...new Set(Object.values(manifest))].map(n=>JSON.parse(readFileSync('src/pages/dca-profiles/holdings-'+n+'.json'))));\nconst histories=Object.entries(ASSETS).map(([id,a])=>({id,name:a.label,isin:a.isin,currency:a.currency,convention:a.historyConvention??a.valuationBasis??a.basis??a.field??a.priceMethod??a.variant??a.methodNote,first:a.points?.[0]?.date,last:a.points?.at(-1)?.date,points:a.points?.length??0,sourceUrls:a.sourceUrls??[],sourceCheckedAt:a.checkedAt??null,latestMonthlyControl:controls[id]??null,configuredAutomation:config.get(id)??null,annualPriceYears:getAnnualReturnStartYears(id),intervals:(a.points??[]).slice(1).map((p,i)=>({start:a.points[i].date,end:p.date,...qualifyHistoryWindow(a,a.points[i].date,p.date)}))}));\nconst supports=Object.entries(references).map(([id,r])=>{const h=holdings[id],a=portfolioAnalytics([{asset:id,isin:r.isin,label:r.name,weight:100}],references,holdings,now);const field=n=>r[n]?{asOf:r[n].asOf,checkedAt:r[n].checkedAt??null,source:r[n].sourceUrl,basis:r[n].basis,method:r[n].method,rows:r[n].rows??[]}:null;return{id,isin:r.isin,name:r.name,outside:r.outsideClassification??null,countries:field('countries'),sectors:field('sectors'),holdings:h?{asOf:h.asOf,checkedAt:h.checkedAt??null,source:h.sourceUrl,basis:h.basis,scope:h.scope,weightBasis:h.weightBasis??null,accessAttempts:h.accessAttempts??[],complete:h.complete,approximation:h.approximation??false,rows:h.rows?.length,total:h.rows?.reduce((s,r)=>s+r.weightPct,0),unidentifiedPositions:h.rows?.filter(r=>!r.isin).map(r=>({name:r.name,weightPct:r.weightPct,sedol:r.sedol??null,ticker:r.ticker??null}))??[],excludedWeightPctByType:h.excludedWeightPctByType,navReconciliation:h.navReconciliation}:null,qualification:a.qualification,unavailable:a.unavailable,incompatiblePairs:a.incompatiblePairs}});\nconst previous=JSON.parse(readFileSync(out+'/archive-index-ids.json'));const indices=[...new Set([...previous,...SHEETS.map(s=>s.id),...Object.keys(INDEX_FACTS)])].map(id=>{const h=INDEX_FACTS[id]??{},date=CURRENT_INDEX_KEYS[id]??Object.keys(h).filter(d=>/^\\d{4}-\\d{2}-\\d{2}$/.test(d)).sort().at(-1)??(h.methodology?'methodology':null);return{id,inSelector:SHEETS.some(s=>s.id===id),facts:CURRENT_INDEX_SNAPSHOTS[id]??h[date]??null,concentration:getIndexConcentration(id,now)}});\nconst cases=JSON.parse(readFileSync(out+'/archive-cases-79.json'));const windows=cases.map(c=>({...c,start:(c.year-1)+'-12',end:c.year+'-12',routes:Object.entries(ASSETS).filter(([,a])=>a.isin===c.isin).map(([id,a])=>({id,currency:a.currency,convention:a.historyConvention??a.priceMethod,qualification:qualifyHistoryWindow(a,(c.year-1)+'-12',c.year+'-12')}))})).map(c=>({...c,qualified:c.routes.some(r=>r.qualification.qualified)}));if(windows.length!==79||windows.some(r=>r.previouslyQualified&&!r.qualified))throw Error('Original79scope or valid-window regression');const sourceCommit=execFileSync('git',['rev-parse','HEAD'],{encoding:'utf8'}).trim();\nwriteFileSync(out+'/family.json.gz',gzipSync(JSON.stringify({sourceCommit,evaluatedAt:now.toISOString(),histories,supports,indices,meaning:'Consumer-engine extraction; configured producer is not supplier execution proof'})));writeFileSync(out+'/windows-79.json',JSON.stringify({sourceCommit,rows:windows},null,2));console.log('Current engine',histories.length,'routes,',supports.length,'supports,',indices.length,'index refs;',windows.filter(r=>r.qualified).length,'/79; original valid windows preserved');\n")
